// HPW Act v2.13.1 — Sistem nasıl çalışır? (RAPOR modu, HPW marka formatı). Bütün ekranlar v2.13.1 DOLU DEMO'dan; işaretler görüntünün üstüne eklenmiştir.
const H = require('/mnt/skills/plugins/hpw-sunum-formati/assets/hpw.js');
const fs = require('fs');
const LEG = JSON.parse(fs.readFileSync('/tmp/k2/legends.json', 'utf8'));
const IMG = (n) => `/tmp/k2/img/${n}.jpg`;
const C = H.C, G = H.G, txt = (o) => Object.assign({ fontFace: 'Poppins', margin: 0, valign: 'top', isTextBox: true }, o);
function card(s, o) {
  const bg = o.fill || C.SAND, koyu = bg === C.RED || bg === C.INK || bg === C.INK_WARM;
  s.addShape('rect', { x: o.x, y: o.y, w: o.w, h: o.h, fill: { color: bg }, line: { type: 'none' } });
  let y = o.y + 0.18;
  if (o.etiket) { s.addText(H.trUpper(o.etiket), txt({ x: o.x + 0.22, y, w: o.w - 0.44, h: 0.24, fontSize: 9, bold: true, charSpacing: 1.5, color: koyu ? C.YELLOW : C.RED })); y += 0.30; }
  if (o.baslik) { const bs = o.baslikSize || 14; const bh = Math.ceil(String(o.baslik).length / Math.max(1, Math.floor((o.w - 0.54) / (bs * 0.56 / 72)))) * (bs * 1.25 / 72); s.addText(o.baslik, txt({ x: o.x + 0.22, y, w: o.w - 0.44, h: bh + 0.05, fontSize: bs, bold: true, color: koyu ? C.WHITE : C.INK })); y += bh + 0.14; }
  if (o.metin) s.addText(o.metin, txt({ x: o.x + 0.22, y, w: o.w - 0.44, h: o.h - (y - o.y) - 0.18, fontSize: o.metinSize || 11, color: koyu ? C.GRAY_LT : C.GRAY_1, lineSpacing: (o.metinSize || 11) * 1.45 }));
}
