let shots = 0; const shotNames = new Set();
const BOLUMLER = ['Sisteme genel bakış', 'Roller ve görevler', 'Sistem bileşenleri', 'Sonuçlar nasıl okunur?', 'Hedef oluşturma', 'Yapay zekâ yokken süreç', 'Yapay zekâ kullanıldığında süreç', 'Yapay zekâ planının 10 bölümü', 'Yapay zekâ ile / yapay zekâ olmadan', 'Aksiyonlar nasıl çalışır?', 'Kanıt, gerçekleşme ve doğrulama', 'OpenAI bağlantısı', 'Güvenlik ve şirket ayrımı', 'Aktör bazlı senaryolar', 'Baştan sona örnek', 'Sık yapılan yanlış anlamalar', 'Ekran ekran sözlük', 'Kapanış'];
const divider = (no, aciklama, sagUst) => H.divider(pres, { no, toplam: BOLUMLER.length, baslik: BOLUMLER[no - 1], aciklama, sagUst });

/* ekran görüntülü slayt: sol görsel, sağ numaralı açıklama; 8'den fazla işaret ikinci slayta taşar */
function shot(o) {
  const leg = o.legend === undefined ? (LEG[o.img] || []) : o.legend; const per = o.kutu ? 6 : 8; const parts = []; for (let i = 0; i < leg.length; i += per) parts.push(leg.slice(i, i + per)); if (!parts.length) parts.push([]);
  parts.forEach((part, pi) => {
    const { slide, band } = H.content(pres, { eyebrow: o.eyebrow, h1: parts.length > 1 ? `${o.h1} (${pi + 1}/${parts.length})` : o.h1, lede: o.lede, takeaway: o.takeaway });
    const iw = o.full ? 12.09 : 7.05, ih = iw * (1290 / 2040);
    slide.addImage({ path: IMG(o.img), x: band.x, y: band.y, w: iw, h: ih }); shots++; shotNames.add(o.img);
    if (!o.full) {
      const rx = band.x + iw + 0.28, rw = band.w - iw - 0.28; let y = band.y;
      if (o.kutu) { card(slide, { x: rx, y, w: rw, h: 1.55, fill: C.INK, etiket: o.kutu.etiket, metin: o.kutu.metin, metinSize: 10.5 }); y += 1.70; }
      if (part.length) {
        slide.addText(part.map((l, i) => ({ text: `${l[0]}  ${l[1]}`, options: { bullet: false, breakLine: i < part.length - 1, paraSpaceAfter: 5 } })), txt({ x: rx, y, w: rw, h: band.y + band.h - y, fontSize: 10.5, color: C.INK, lineSpacing: 15 }));
      } else if (o.metin) {
        slide.addText(o.metin, txt({ x: rx, y, w: rw, h: band.y + band.h - y, fontSize: 11, color: C.GRAY_1, lineSpacing: 16 }));
      }
    }
    if (o.full && o.metin) slide.addText(o.metin, txt({ x: band.x, y: band.y + ih + 0.15, w: band.w, h: band.h - ih - 0.15, fontSize: 10.5, color: C.GRAY_1, lineSpacing: 15 }));
    if (o.notlar) slide.addNotes(o.notlar);
  });
}
/* kart ızgarası */
function kartlar(o) {
  const { slide, band } = H.content(pres, { eyebrow: o.eyebrow, h1: o.h1, lede: o.lede, takeaway: o.takeaway });
  const n = o.items.length, cols = o.cols || Math.min(n, 3), rowsN = Math.ceil(n / cols), cs = H.cols(cols), rs = H.rows(rowsN, { gutter: 0.18 });
  o.items.forEach((it, i) => { const c = cs[i % cols], r = rs[Math.floor(i / cols)]; card(slide, { x: c.x, y: r.y, w: c.w, h: r.h, fill: it.fill || (i === 0 && o.ilkKirmizi ? C.RED : C.SAND), etiket: it.etiket, baslik: it.baslik, metin: it.metin, baslikSize: it.baslikSize || (rowsN >= 2 ? 12 : 14), metinSize: rowsN >= 2 ? 10 : 11 }); });
  if (o.notlar) slide.addNotes(o.notlar); return slide;
}
/* süreç akışı: kutular ve oklar, 2 satıra bölünür */
function akis(o) {
  const { slide, band } = H.content(pres, { eyebrow: o.eyebrow, h1: o.h1, lede: o.lede, takeaway: o.takeaway });
  const per = o.per || Math.ceil(o.adimlar.length / (o.satir || 2)), satir = Math.ceil(o.adimlar.length / per); const rs = H.rows(satir, { gutter: 0.35, T: band.y + 0.1, H: band.h - 0.1 });
  o.adimlar.forEach((a, i) => { const r = rs[Math.floor(i / per)], k = i % per, w = (band.w - 0.34 * (per - 1)) / per, x = band.x + k * (w + 0.34); const vur = o.vurgu && o.vurgu.includes(i);
    slide.addShape('rect', { x, y: r.y, w, h: Math.min(r.h, 1.7), fill: { color: vur ? C.RED : C.SAND }, line: { type: 'none' } });
    slide.addText(`${i + 1}`, txt({ x: x + 0.15, y: r.y + 0.12, w: 0.6, h: 0.3, fontSize: 11, bold: true, color: vur ? C.YELLOW : C.RED }));
    slide.addText(a, txt({ x: x + 0.15, y: r.y + 0.42, w: w - 0.3, h: Math.min(r.h, 1.7) - 0.5, fontSize: 10.5, bold: true, color: vur ? C.WHITE : C.INK, lineSpacing: 14 }));
    if (k < per - 1 && i < o.adimlar.length - 1) slide.addText('→', txt({ x: x + w + 0.02, y: r.y + 0.42, w: 0.3, h: 0.4, fontSize: 18, bold: true, color: C.RED, align: 'center' }));
  });
  if (o.notlar) slide.addNotes(o.notlar); return slide;
}
/* iki sütun karşılaştırma */
function kiyas(o) {
  const { slide, band } = H.content(pres, { eyebrow: o.eyebrow, h1: o.h1, lede: o.lede, takeaway: o.takeaway }); const cs = H.cols(2);
  [[o.sol, C.SAND], [o.sag, C.INK]].forEach(([k, fill], i) => { card(slide, { x: cs[i].x, y: band.y, w: cs[i].w, h: band.h, fill, etiket: k.etiket, baslik: k.baslik, baslikSize: 16 });
    slide.addText(k.maddeler.map((m, j) => ({ text: m, options: { bullet: true, breakLine: j < k.maddeler.length - 1, paraSpaceAfter: 8 } })), txt({ x: cs[i].x + 0.22, y: band.y + 1.25, w: cs[i].w - 0.44, h: band.h - 1.45, fontSize: 11.5, color: fill === C.INK ? C.WHITE : C.INK, lineSpacing: 17 })); });
  if (o.notlar) slide.addNotes(o.notlar); return slide;
}
/* madde listesi + sağda büyük vurgu kartı */
function liste(o) {
  const { slide, band } = H.content(pres, { eyebrow: o.eyebrow, h1: o.h1, lede: o.lede, takeaway: o.takeaway });
  const lw = o.kart ? 7.3 : band.w;
  slide.addText(o.maddeler.map((m, j) => ({ text: m, options: { bullet: true, breakLine: j < o.maddeler.length - 1, paraSpaceAfter: 9 } })), txt({ x: band.x, y: band.y, w: lw, h: band.h, fontSize: o.fontSize || 13, color: C.INK, lineSpacing: 20 }));
  if (o.kart) card(slide, { x: band.x + lw + 0.4, y: band.y, w: band.w - lw - 0.4, h: o.kart.h || 2.6, fill: o.kart.fill || C.RED, etiket: o.kart.etiket, baslik: o.kart.baslik, metin: o.kart.metin, baslikSize: 15 });
  if (o.notlar) slide.addNotes(o.notlar); return slide;
}
/* tablo */
function tablo(o) {
  const { slide, band } = H.content(pres, { eyebrow: o.eyebrow, h1: o.h1, lede: o.lede, takeaway: o.takeaway });
  const head = o.head.map((h) => ({ text: h, options: { bold: true, color: C.WHITE, fill: { color: C.INK }, fontSize: o.fs || 9.5, fontFace: 'Poppins' } }));
  const rows = o.rows.map((r) => r.map((c, i) => ({ text: c, options: { fontSize: o.fs || 9.5, fontFace: 'Poppins', color: i === 0 ? C.INK : (c === 'Yapamaz' ? C.GRAY_MID : C.INK), bold: i === 0, fill: { color: i === 0 ? C.SAND : C.WHITE } } })));
  slide.addTable([head, ...rows], { x: band.x, y: band.y, w: band.w, colW: o.colW, border: { type: 'solid', pt: 0.5, color: C.GRAY_LT }, rowH: o.rowH || 0.3, margin: 0.05, valign: 'middle' });
  if (o.notlar) slide.addNotes(o.notlar); return slide;
}
